"use strict";(self.webpackChunkintegrated_retail_kb=self.webpackChunkintegrated_retail_kb||[]).push([["9910"],{1542(e,n,i){i.r(n),i.d(n,{metadata:()=>t,default:()=>h,frontMatter:()=>s,contentTitle:()=>o,toc:()=>d,assets:()=>l});var t=JSON.parse('{"id":"legal-policies/health-and-safety-policy-117","title":"Health and Safety Policy ","description":"Applicable to Singapore, Malaysia, Thailand and Indonesia | 13 August 2026","source":"@site/docs/legal-policies/health-and-safety-policy-117.md","sourceDirName":"legal-policies","slug":"/legal-policies/health-and-safety-policy","permalink":"/docs/legal-policies/health-and-safety-policy","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"health-and-safety-policy-117","title":"Health and Safety Policy ","slug":"/legal-policies/health-and-safety-policy","description":"Applicable to Singapore, Malaysia, Thailand and Indonesia | 13 August 2026"},"sidebar":"tutorialSidebar","previous":{"title":"GDPR Compliance","permalink":"/docs/legal-policies/gdpr-compliance"},"next":{"title":"Health and Safety Policy","permalink":"/docs/legal-policies/health-and-safety-policy"}}'),a=i(4848),r=i(8453);let s={id:"health-and-safety-policy-117",title:"Health and Safety Policy ",slug:"/legal-policies/health-and-safety-policy",description:"Applicable to Singapore, Malaysia, Thailand and Indonesia | 13 August 2026"},o="Health and Safety Policy",l={},d=[{value:"1. Health and Safety Policy Statement",id:"1-health-and-safety-policy-statement",level:2},{value:"2. Scope",id:"2-scope",level:2},{value:"3. Legal Framework",id:"3-legal-framework",level:2},{value:"4. Allocation of Responsibilities",id:"4-allocation-of-responsibilities",level:2},{value:"Integrated Retail",id:"integrated-retail",level:3},{value:"Employees and Contractors",id:"employees-and-contractors",level:3},{value:"5. Key Hazards and Controls",id:"5-key-hazards-and-controls",level:2},{value:"6. Training, Competence and Equipment",id:"6-training-competence-and-equipment",level:2},{value:"7. Incident Reporting and Emergency Arrangements",id:"7-incident-reporting-and-emergency-arrangements",level:2},{value:"8. Review",id:"8-review",level:2}];function c(e){let n={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",ul:"ul",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"health-and-safety-policy",children:"Health and Safety Policy"})}),"\n",(0,a.jsx)(n.p,{children:"Integrated Retail Pte Ltd"}),"\n",(0,a.jsx)(n.p,{children:"Applicable to Singapore, Malaysia, Thailand and Indonesia | 13 August 2026"}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.h2,{id:"1-health-and-safety-policy-statement",children:"1. Health and Safety Policy Statement"}),"\n",(0,a.jsx)(n.p,{children:'Integrated Retail Pte Ltd ("Integrated Retail") is fully aware of its duties and responsibilities toward the health and safety of its employees, contractors, customers and members of the public who may be affected by our survey, installation, maintenance and support activities. It is our intention to maintain the highest possible standard of health and safety on every site we attend, in every country in which we operate. In fulfilling this objective, Integrated Retail has a duty to provide and maintain a safe working environment by reducing risks to a reasonably practicable level. This policy statement and any revision of it shall be communicated to all workers.'}),"\n",(0,a.jsx)(n.p,{children:"Integrated Retail is committed to the elimination of personal injuries, occupational illnesses and damage to equipment and property in all its operations; to the protection of customers, their staff and the general public whenever they come into contact with our work; and to the prevention of pollution and environmental degradation, by:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Setting corporate standards that address our business risk profile by meeting or exceeding the minimum legal requirements of each country in which we operate;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Giving the highest priority to health and safety when weighing commercial, scheduling and technical considerations, including sales commitments and project deadlines;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Providing information, training and supervision to our employees and contractors so that every installation and service call is carried out safely and in accordance with FootfallCam's approved installation procedures;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Selecting and monitoring our installation contractors on the basis of demonstrated safety competence, not on price or availability alone;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Complying with the site rules, permit-to-work systems and contractor induction requirements of every customer whose premises we enter;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Requiring continuous communication between employees at all levels, so that every person understands their responsibility to report immediately any situation that could jeopardise the well-being of themselves or any other person."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.h2,{id:"2-scope",children:"2. Scope"}),"\n",(0,a.jsx)(n.p,{children:"This policy applies to all employees of Integrated Retail in Singapore, Malaysia, Thailand and Indonesia; to all contractors and subcontractors engaged by us to perform survey, installation, commissioning, maintenance or decommissioning work; to work at our own premises and at customer or third-party sites; and to travel between sites on company business."}),"\n",(0,a.jsx)(n.p,{children:"Where this policy, local law and the customer's own safety requirements differ, the most stringent requirement applies."}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.h2,{id:"3-legal-framework",children:"3. Legal Framework"}),"\n",(0,a.jsx)(n.p,{children:"Integrated Retail recognises its obligations under the occupational safety and health legislation of each territory in which it operates:"}),"\n",(0,a.jsx)(n.p,{children:"Country"}),"\n",(0,a.jsx)(n.p,{children:"Principal legislation and regulator"}),"\n",(0,a.jsx)(n.p,{children:"Singapore"}),"\n",(0,a.jsx)(n.p,{children:"Workplace Safety and Health Act 2006 and subsidiary regulations, including Risk Management and Work at Heights. Regulator: Ministry of Manpower (MOM)."}),"\n",(0,a.jsx)(n.p,{children:"Malaysia"}),"\n",(0,a.jsx)(n.p,{children:"Occupational Safety and Health Act 1994 (Act 514), as amended with effect from 1 June 2024, extending the Act to all places of work. Regulator: Department of Occupational Safety and Health (DOSH)."}),"\n",(0,a.jsx)(n.p,{children:"Thailand"}),"\n",(0,a.jsx)(n.p,{children:"Occupational Safety, Health and Environment Act B.E. 2554 (2011) and associated Ministerial Regulations. Regulator: Department of Labour Protection and Welfare (DLPW)."}),"\n",(0,a.jsx)(n.p,{children:"Indonesia"}),"\n",(0,a.jsx)(n.p,{children:"Law No. 1 of 1970 on Work Safety and Government Regulation No. 50 of 2012 on the Occupational Safety and Health Management System (SMK3). Regulator: Ministry of Manpower."}),"\n",(0,a.jsx)(n.p,{children:"Our arrangements are aligned with the principles of ISO 45001:2018 and with the installation and safety procedures issued by FootfallCam as our principal supplier."}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.h2,{id:"4-allocation-of-responsibilities",children:"4. Allocation of Responsibilities"}),"\n",(0,a.jsx)(n.h3,{id:"integrated-retail",children:"Integrated Retail"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must observe, implement and fulfil its responsibilities under the relevant health and safety law of each country in which it operates;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must provide adequate resources \u2014 competent personnel, access equipment, tools, personal protective equipment and realistic timeframes \u2014 to allow this policy to be implemented in practice;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must make regular assessments of health and safety performance, and complete a risk assessment for every category of work we undertake, with a site-specific assessment where conditions require it;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must provide information, training and supervision for all employees and contractors regarding the correct and comprehensive installation procedure;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must verify the competence, certification and insurance of every contractor before engagement, and monitor their performance on site;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must report and investigate incidents and accidents occurring during our work, notify the authority, customer and FootfallCam where required, and share the lessons learned across all four territories;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must not permit commercial pressure or customer deadlines to override a safety decision made on site."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Each Country Manager is accountable for implementation of this policy within their territory, including compliance with local statutory requirements such as safety officer or safety committee appointments, and for maintaining local records of risk assessments, training, inspections and incidents."}),"\n",(0,a.jsx)(n.h3,{id:"employees-and-contractors",children:"Employees and Contractors"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Should comply with all safety procedures, method statements, permits, site rules and directions given to them;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must take reasonable care for their own health and safety and that of any other person affected by their acts or omissions;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must use the personal protective equipment and access equipment provided, and use it correctly;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must not wilfully interfere with or misuse any item or facility provided in the interests of health and safety;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must not undertake any task for which they have not been trained, licensed or certified;"}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Must, in accordance with agreed procedures for accident and incident reporting, report potential and actual hazards to Integrated Retail without delay."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Any worker may stop work and withdraw from an unsafe situation without fear of dismissal, penalty or other detriment."}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.h2,{id:"5-key-hazards-and-controls",children:"5. Key Hazards and Controls"}),"\n",(0,a.jsx)(n.p,{children:"Our risk assessments address, as a minimum:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Work at height \u2014 ceiling and wall-mounted installations. Suitable inspected access equipment is used; working from shelving, display fixtures or unsecured furniture is prohibited; operators of powered access equipment must hold valid certification."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Electrical work \u2014 mains and PoE connections are made only by persons competent and, where required by law, licensed. Circuits are isolated and proved dead before work begins."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Occupied and public spaces \u2014 work is scheduled out of trading hours where practicable; work areas are barricaded and signed, escape routes kept clear, and falling objects prevented."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Drilling, dust and ceiling voids \u2014 dust suppression and eye, hearing and respiratory protection as assessed. Work stops immediately and is reported if suspected asbestos or other hazardous material is disturbed."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Manual handling \u2014 loads and routes assessed; team lifting or mechanical aids used as required."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Lone working \u2014 prohibited for work at height and live electrical work. Where permitted, a check-in and check-out procedure applies."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Driving and fatigue \u2014 valid licences, journey planning, adequate rest between night or early-morning installations, and no mobile device use while driving."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Waste \u2014 packaging, cable offcuts, batteries and end-of-life electronic equipment are disposed of through licensed channels."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Where the customer or mall management operates a permit-to-work or contractor induction system, no work commences until the permit is issued and understood by everyone on site."}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.h2,{id:"6-training-competence-and-equipment",children:"6. Training, Competence and Equipment"}),"\n",(0,a.jsx)(n.p,{children:"Every employee and contractor receives an induction covering this policy, our safe systems of work, incident reporting and emergency arrangements before undertaking site work. Task-specific training and certification is required and recorded for work at height, powered access equipment, electrical work and first aid, in line with the requirements of each country. Technical training on FootfallCam products and installation procedures is provided by Integrated Retail and refreshed when the product range or procedure changes."}),"\n",(0,a.jsx)(n.p,{children:"Personal protective equipment identified by risk assessment is provided free of charge, inspected before use and replaced when damaged or expired. PPE is the last line of defence, not a substitute for controlling the hazard."}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.h2,{id:"7-incident-reporting-and-emergency-arrangements",children:"7. Incident Reporting and Emergency Arrangements"}),"\n",(0,a.jsx)(n.p,{children:"All accidents, injuries, occupational illnesses, near misses and property damage must be reported to the Site Supervisor and Country Manager immediately and recorded in the incident register. Reportable incidents are notified to the relevant authority within the timeframe prescribed by local law, and to the customer and our insurers as required. Every incident is investigated to identify root causes, with corrective actions assigned, tracked and verified."}),"\n",(0,a.jsx)(n.p,{children:"Before starting work, site teams confirm the location of first-aid provision, fire exits, assembly points and emergency contacts, and comply with the site occupier's emergency procedures."}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.h2,{id:"8-review",children:"8. Review"}),"\n",(0,a.jsx)(n.p,{children:"This policy will be regularly reviewed in the light of legislation and company changes, and at least annually. Safety performance is reported to the Managing Director and reviewed at management level. We seek the co-operation of all employees and contractors in realising our safety and health objectives. All workers will be advised, in writing or by display, of any changes and of the arrangements for their implementation."})]})}function h(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},8453(e,n,i){i.d(n,{R:()=>s,x:()=>o});var t=i(6540);let a={},r=t.createContext(a);function s(e){let n=t.useContext(r);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),t.createElement(r.Provider,{value:n},e.children)}}}]);